def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y, x))

            def bbox_area(points):
                ys = [y for y, x in points]
                xs = [x for y, x in points]
                return (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1)

            layers = sorted(colors, key=lambda color: bbox_area(colors[color]), reverse=True)
            reversed_layers = list(reversed(layers))
            mapping = dict(zip(layers, reversed_layers))

            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]

    return out
